xml.Script:
        clBlue   := '0000C8';
        clGreen  := '009600';
        clRed    := 'C80000';
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        R := 0.65;
        H := R * sqrt(3) / 2;
        D  := R * 3 / 2 / sqrt(7);

        sAngle := PI * 2 / 3;
        for i := 0 to 2 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
        end;

        A1 := ArcCos(1/8);
        A2 := ArcCos(-3/4);
